import java.io.BufferedInputStream

private const val SIZE = 1_000_002

private val s = IntArray(SIZE)
private val p = IntArray(SIZE)
private var np = 0
private var minimum = Int.MAX_VALUE

private fun sieve() {
    for (i in 2 until SIZE) {
        if (s[i] == 0) {
            p[np++] = i

            var j = 2
            while (i * j < SIZE) {
                s[i * j] = 1
                j++
            }
        }
    }
}

private fun solve(value: Int, level: Int) {
    var x = value

    if (x < minimum) {
        minimum = x
    }

    if (level == 0) {
        return
    }

    var largestFactor = -1
    var remaining = x
    var i = 0

    while (p[i].toLong() * p[i] <= x.toLong()) {
        if (remaining % p[i] == 0) {
            largestFactor = maxOf(largestFactor, p[i])
            while (remaining % p[i] == 0) {
                remaining /= p[i]
            }
        }
        i++
    }

    if (remaining > 1 && remaining != x) {
        largestFactor = maxOf(largestFactor, remaining)
    }

    if (largestFactor == -1) {
        return
    }

    if (level == 1) {
        x = x - largestFactor + 1
        if (x < minimum) {
            minimum = x
        }
        return
    }

    var d = x - largestFactor + 1
    val end = largestFactor * (x / largestFactor)
    while (d < end) {
        solve(d, level - 1)
        d++
    }
}

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32 && c != -1)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var value = 0
        while (c > 32 && c != -1) {
            value = value * 10 + c - '0'.code
            c = readByte()
        }
        return value * sign
    }
}

fun main() {
    s[0] = 1
    s[1] = 1
    sieve()

    val scanner = FastScanner()
    val x2 = scanner.nextInt()

    solve(x2, 2)
    print(minimum)
}

